const p = drone.getPlayer();
const crafted = drone.craft({ filter: 'chest', count: 2 });
const made = Number((crafted && crafted.crafted) || 0);
if (!crafted || crafted.ok === false || made < 2) {
  return { ok: false, error: 'need 2 chests in the drone inventory', craft: crafted, hint: 'gather wood/planks or take them from the player first' };
}
const a = drone.placeBlock({ x: p.blockX + 1, y: p.blockY, z: p.blockZ, block: 'chest' });
const b = drone.placeBlock({ x: p.blockX + 2, y: p.blockY, z: p.blockZ, block: 'chest' });
return { ok: !!(a.placed && b.placed), placed: [a.placed, b.placed].filter(Boolean).length };
